var cookieName="complianceCookie";function createBanner(){var bodytag=document.getElementsByTagName("body")[0],div=document.createElement("div");div.setAttribute("id","cookie-law"),div.innerHTML='<span>This website uses cookies. See <a href="/cookie-policy.html" rel="nofollow" title="Privacy &amp; Cookies Policy">cookie policy</a> for more information.</span> <div class="accept-decline"><div class="btn-decline"><a class="decline-cookie-banner" href="javascript:void(0);" onclick="cookieAccept(false);"><span>Decline</span></a></div><div class="btn-accept"><a class="close-cookie-banner" href="javascript:void(0);" onclick="cookieAccept(true);"><span>Accept</span></a></div></div>',bodytag.insertBefore(div,bodytag.firstChild)}function createCookie(name,value){var date=new Date;date.setTime(date.getTime()+31536e6);var expires="; expires="+date.toGMTString();document.cookie=name+"="+value+expires+"; path=/"}function checkCookie(name){for(var nameEQ=name+"=",ca=document.cookie.split(";"),i=0;i<ca.length;i++){for(var c=ca[i];" "==c.charAt(0);)c=c.substring(1,c.length);if(0==c.indexOf(nameEQ))return c.substring(nameEQ.length,c.length)}return null}function createComplianceCookie(b){createCookie(cookieName,b)}function cookieAccept(b){createComplianceCookie(b);var element=document.getElementById("cookie-law");element.parentNode.removeChild(element)}function storageAllowed(){return"true"==checkCookie(cookieName)}function onLoad(){checkCookie(cookieName)||createBanner()}function canUseLocalStorage(){return window.localStorage&&storageAllowed()}function setLocalStorageItem(key,data){canUseLocalStorage()&&window.localStorage.setItem(key,JSON.stringify(data))}function getLocalStorageItem(key,deflt){if(canUseLocalStorage()){var data=window.localStorage.getItem(key);if(data)return JSON.parse(data)}return deflt}